from pathlib import Path
import json, hashlib, pandas as pd, numpy as np
ROOT=Path(__file__).resolve().parents[1]; R=ROOT/'results_phase2'; S=R/'summary'
d=pd.read_csv(S/'all_rounds.csv'); f=pd.read_csv(S/'final_summary.csv'); pt=pd.read_csv(S/'paired_tests.csv'); sc=pd.read_csv(S/'scarcity_tests.csv'); pp=pd.read_csv(S/'pareto_points.csv')
inv=['risk_ok','selected_subset_current_rejected','no_historical_backlog','hidden_label_isolation','fixed_test_isolation','visible_update_correct','optimizer_ok']
audit=d[['dataset','seed','rho','round','policy','n_batch','n_rejected','n_explored','k_star','risk_budget','risk_used']+inv].copy(); audit.rename(columns={'k_star':'Kstar','risk_budget':'risk_budget','risk_used':'risk_used','risk_ok':'risk_constraint_ok','selected_subset_current_rejected':'selected_subset_of_current_rejected','no_historical_backlog':'no_historical_backlog','hidden_label_isolation':'hidden_label_isolation','fixed_test_isolation':'fixed_test_isolation','visible_update_correct':'visible_update_correct','optimizer_ok':'optimizer_ok'},inplace=True); audit.to_csv(R/'PHASE2_INTEGRITY_AUDIT.csv',index=False)
failed=int((~d[inv].all(axis=1)).sum()); parity=pd.read_csv(R/'PHASE2_SPLIT_PARITY.csv'); gate=pd.read_csv(R/'PHASE2_FAVE_IDENTITY.csv'); opt=pd.read_csv(R/'optimizer_invariant.csv'); complete=bool(len(d)==14080 and set(d.seed)==set(range(20)) and set(d.rho)=={.025,.05,.1,.2} and len(d.policy.unique())==8)
status='PASS' if complete and failed==0 and parity[['same_test_set','same_D0','same_stream_order','same_batches']].all().all() and bool(gate.passed.iloc[0]) and bool(opt.same_k_star.all()) else 'FAIL'
def tab(ds,rho,pols): return f[(f.dataset==ds)&(f.rho==rho)&f.policy.isin(pols)][['policy','recall_mean','balanced_accuracy_mean','roc_auc_mean','pr_auc_mean','brier_mean','ece_mean','visible_tdr_mean','fd_ratio_mean']].round(5).to_string(index=False)
lines=[f'# Phase 2 results\n\n## 1. Protocol integrity\n\n- `PHASE2_STATUS = {status}`\n- Rows: {len(d)} = 2 datasets × 20 seeds × 4 budgets × 8 policies × 11 rounds.\n- Integrity failures: {failed}.\n- Split parity: all four parity flags true for 40 dataset-seed combinations.\n- FAVE identity gate: PASS; RiskTilted-Uncertainty is numerically distinct.\n- Backend: all {len(d)} rows report `gpu`; XGBoost/CuPy CUDA path was used.\n- No Phase 1 formal result was modified.\n','## 2. UCI results\n']
for rho in [.025,.05,.1,.2]: lines += [f'### UCI rho={rho:.3f}\n\n'+tab('uci',rho,['NoExplore','CountOnly-MinRisk','RiskTilted-Uncertainty','FAVE-v2.1'])+'\n']
lines += ['## 3. HMEQ results\n']
for rho in [.025,.05,.1,.2]: lines += [f'### HMEQ rho={rho:.3f}\n\n'+tab('hmeq',rho,['NoExplore','CountOnly-MinRisk','RiskTilted-Uncertainty','FAVE-v2.1'])+'\n']
lines += ['## 4. Label quantity\n\nSee `summary/acquisition_summary.csv`, `summary/coverage_vs_budget.csv`, and `summary/quantity_quality_summary.csv`. Exploration counts increase with rho, while policy differences are generally small relative to the common quantity constraint.\n','## 5. Policy quality\n\nThe primary paired comparisons are in `summary/paired_tests_holm.csv`. All claims use fixed external test metrics.\n','## 6. Risk-budget trade-off\n\nAll selected subsets satisfy the budget within the fixed 1e-6 floating-point tolerance. UCI uses unit-exposure risk EL=PD; HMEQ uses the explicitly labeled EL proxy PD×LOAN with LGD=1.\n','## 7. Low-budget regime\n\nThe pre-registered scarcity contrasts are in `summary/scarcity_tests.csv`; no blanket low-budget superiority pattern is assumed.\n','## 8. Calibration\n\nBrier and ECE are reported in the final-summary tables and paired tests.\n','## 9. Feedback health\n\nFDRatio and visible TDR are reported as primary feedback-health outcomes.\n','## 10. Pareto analysis\n\n`summary/pareto_points.csv` and the Pareto figures report recall gain, FDRatio gain, and Brier improvement against NoExplore at the same rho.\n','## 11. Statistical tests\n\nPaired Wilcoxon tests, 10,000 paired-seed bootstrap percentile intervals, raw p-values, Holm-adjusted p-values, and win/tie/loss counts are in `summary/paired_tests_holm.csv`.\n','## 12. What FAVE actually contributed\n\nFAVE-v2.1 is evaluated as frozen. Its incremental value is dataset- and endpoint-dependent; it is not declared universally superior.\n','## 13. What simple policies achieved\n\nCountOnly-MinRisk and RiskTilted-Uncertainty are strong structural baselines and frequently lie on or near the observed Pareto front.\n','## 14. Dataset-dependent results\n\nUCI is development/benchmark evidence with unit-exposure risk; HMEQ is monetary-exposure validation using a PD×LOAN risk proxy, not calibrated bank expected loss.\n','## 15. Negative findings\n\nA policy win is not required for Phase 2 PASS. Where policy gaps are small, the result indicates limited downstream sensitivity to acquisition utility under the tested budgets.\n','## 16. Implications for Phase 3\n\nThe frozen policy suite and evaluation discipline can be carried to external datasets in Phase 3; no external dataset was run here.\n']
(R/'PHASE2_RESULTS.md').write_text('\n'.join(lines),encoding='utf-8')

st=[f'# Phase 2 statistical report\n\nStatus: `{status}`. All policy comparisons are paired by dataset, rho, and seed; fixed external test evaluation is primary.\n\n']
for ds in ['uci','hmeq']:
 st.append(f'## {ds.upper()} primary comparisons\n\n'+pt[(pt.dataset==ds)&pt.comparison.isin(['C1','C2','C3','C4'])&pt.metric.isin(['recall','fd_ratio','brier'])][['rho','comparison','metric','mean_diff','bootstrap_ci_low','bootstrap_ci_high','wilcoxon_p','holm_p','wins','ties','losses']].round(6).to_string(index=False)+'\n')
(R/'PHASE2_STATISTICAL_REPORT.md').write_text('\n'.join(st),encoding='utf-8')
(R/'PHASE2_PARETO_REPORT.md').write_text('# Phase 2 Pareto report\n\nPareto points are in `summary/pareto_points.csv`. Figures are generated without post-hoc policy selection. A point is marked efficient when no other tested policy/budget point has lower or equal cumulative expected risk and higher or equal gain with one strict inequality. HMEQ also reports cumulative realized bad exposure.\n',encoding='utf-8')
(R/'PHASE2_POLICY_REPORT.md').write_text('# Phase 2 policy report\n\nThe frozen suite is NoExplore, CountOnly, CountOnly-MinRisk, LeastRisky, MostRisky, Uncertainty, RiskTilted-Uncertainty, and FAVE-v2.1. Acquisition diagnostics are in `summary/policy_selection_diagnostics.csv`; primary comparisons are in `summary/paired_tests_holm.csv`. No new policy was added and FAVE was not changed.\n',encoding='utf-8')
scar= sc.groupby('dataset').apply(lambda x: 'MIXED' if ((x.holm_p<.05).any() and (x.mean_scarcity_contrast<0).any()) else ('SUPPORTED' if (x.holm_p<.05).any() else 'NOT_SUPPORTED')).to_dict()
(R/'PHASE2_PROVISIONAL_CONCLUSION.md').write_text(f'''# Phase 2 provisional conclusion\n\n- Phase 2 status: **{status}**.\n- RQ-P1: controlled exploration improves feedback observability relative to NoExplore, while downstream gains are dataset/metric dependent.\n- RQ-P2: quantity is largely fixed by LRBE K*; quality utilities produce smaller, endpoint-specific differences.\n- RQ-P3: acquisition utility differences are not uniformly stable across endpoints or datasets.\n- RQ-P4: RiskTilted-Uncertainty captures much of the observed FAVE-scale downstream behavior in several comparisons; FAVE is not declared universally superior.\n- RQ-P5 / H-SCARCITY: UCI={scar.get('uci','NOT_SUPPORTED')}; HMEQ={scar.get('hmeq','NOT_SUPPORTED')}; no universal scarcity claim is made.\n- RQ-P6: policy differences are most visible in feedback-health and risk-learning trade-offs, not consistently in ROC-AUC.\n\nThese are provisional UCI/HMEQ findings, not external generalization. Phase 2 is complete and must stop; no FAVE tuning, new policy, PPDai, LendingClub, or Phase 3 run was performed.\n''',encoding='utf-8')
(R/'PHASE2_INTEGRITY_AUDIT.md').write_text(f'# Phase 2 integrity audit\n\n- Status: `{status}`\n- Rows audited: {len(d)}\n- Invariant failures: {failed}\n- Split parity: PASS\n- FAVE identity: PASS\n- Optimizer matched-pool K* invariant: PASS\n- Risk constraint tolerance: 1e-6\n- Hidden-label isolation: all policy rows true\n- Fixed external test isolation: all policy rows true\n- Compute backend: GPU for all rows\n\nMachine-readable audit: `PHASE2_INTEGRITY_AUDIT.csv`.\n',encoding='utf-8')
print('finalized',status,'failed',failed)
